INSERT INTO `lsp_jenis` VALUES (1,'P3','LSP Pihak Ketiga','LSP yang didirikan oleh asosiasi industri dan/atau asosiasi profesi dengan tujuan melaksanakan sertifikasi kompetensi kerja untuk sektor dan atau profesi tertentu sesuai ruang lingkup yang diberikan oleh BNSP.'),(2,'P2','LSP Pihak Kedua','LSP yang didirikan oleh industri atau instansi dengan tujuan utama melaksanakan sertifikasi kompetensi kerja terhadap sumber daya manusia lembaga induknya, sumber daya manusia dari pemasoknya dan /atau sumber daya manusia dari jejaring kerjanya, sesuai ruang lingkup yang diberikan oleh BNSP'),(3,'P1-Industri','LSP Pihak Kesatu Industri','LSP yang didirikan oleh industri atau instansi dengan tujuan utama melaksanakan sertifikasi kompetensi kerja terhadap sumber daya manusia lembaga induknya, sesuai ruang lingkup yang diberikan oleh BNSP'),(4,'P1-LDP','LSP Pihak Kesatu Lembaga Pendidikan dan/atau Pelatihan','LSP yang didirikan oleh lembaga pendidikan dan atau pelatihan dengan tujuan utama melaksanakan sertifikasi kompetensi kerja terhadap peserta pendidikan/pelatihan berbasis kompetensi dan /atau sumber daya manusia dari jejaring kerja lembaga induknya, sesuai ruang lingkup yang diberikan oleh BNSP');
/*!40000 ALTER TABLE `lsp_jenis` ENABLE KEYS */;
UNLOCK TABLES;

