INSERT INTO `mutudoc_doc` VALUES (4,2,11,'Panduan Mutu LSP Pendidikan dan Pembinaan Manajemen','Dalam rangka mendukung pelaksanaan sertifikasi bagi para profesi terhadap kompetensi yang dimilikinya, perlu adanya penerapan komitmen Manajemen LSP Pendidikan dan Pembinaan Manajemen (PPM) sebagaimana dituangkan dalam penyusunan Panduan Mutu yang telah disesuaikan dengan Pedoman BNSP 201-Tahun 2014 tentang persyaratan umum lembaga sertifikasi profesi, dan ditunjang dengan Pedoman BNSP 202 – Tahun 2014 tentang pembentukan lembaga sertifikasi profesi','2021-04-21','PM-IDN-LSP-02/2021',1,'Bagian Administrasi LSP','Ketua LSP dan Ketua Pengarah LSP','1697012905a2daa9f8d8582bbbeb1ddca017c156b1.pdf','2023-10-11 08:28:25');
